// Code generated by Claude (Anthropic), an AI system.
// The AI's part of the two panels: "Analyse with AI" (an explanation of the readings the panel shows) and the
// "Anonymous session with AI" (a chat). It asks before anything downloads, shows the progress, says plainly when
// this browser cannot run the AI, and always shows "Rules this AI follows". Everything else in the panels works
// without it. Styles: support.css (.ai-*). Rules: src/ai-rules.js. Engine: src/ai.js.
import { h, fill, btn, supIcon } from './support.js';
import { AI_MODEL } from './ai-model.js';
import { visibleRules, spaceRules, heldCounts, ruleById } from './ai-rules.js';
import { aiSupport, aiState, modelSource, isStored, startAi, askAi, interrupt, forgetTalk } from './ai.js';

// The person said yes on this page: the model is then stored, and later panels start it without asking again.
let agreed = false;
// The talk now on screen (memory only). endTalk() forgets it when the panel closes.
let talk = null;

const reduceMotion = () => Boolean(globalThis.matchMedia && globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches);
const LABEL = 'AI draft, not a diagnosis; the levels come from the automation';

// "Rules this AI follows": the short list, open by default, with where the full list lives. Under it a second
// list, "How this AI works in space": the rules marked space: true, in plain words with their NASA IDs.
export function rulesList(kind) {
  const held = Object.values(heldCounts()).reduce((n, x) => n + (Number(x) || 0), 0);
  const space = spaceRules(kind);
  return h('details', { class: 'ai-rules', open: true },
    h('summary', {}, 'Rules this AI follows'),
    h('ul', {}, ...visibleRules(kind).map((r) => h('li', {}, r.short))),
    space.length ? h('p', { class: 'ai-space-title' }, 'How this AI works in space') : null,
    space.length ? h('ul', { class: 'ai-space' }, ...space.map((r) => h('li', {}, `${r.spaceShort} `, h('span', { class: 'ai-nasa' }, `(${r.nasa})`)))) : null,
    h('p', { class: 'note' }, `Code checks every answer before you see it; an answer that breaks a rule is replaced by a fixed text that names the rule.${held ? ` Held back on this computer so far: ${held} (only the number is kept, never the text).` : ''} The full list, with where each rule comes from, is in src/ai-rules.js.`));
}

// The consent card: what downloads, how big, where it runs, that nothing written leaves this computer.
function consentCard(source, kind, { onYes, onNo }) {
  const local = source.kind === 'local';
  return h('div', { class: 'ai-card', role: 'group', 'aria-label': 'Start the AI on this computer' },
    h('p', { class: 'tp-title' }, 'Start the AI on this computer?'),
    h('ul', { class: 'links' },
      h('li', {}, h('b', {}, local ? 'What loads: ' : 'What downloads: '), `the AI model ${AI_MODEL.name} (${AI_MODEL.license}), about ${AI_MODEL.downloadMB} MB, once, from ${source.where}. The engine that runs it, WebLLM, is part of this program.`),
      h('li', {}, h('b', {}, 'Where it runs: '), `on this computer's graphics chip (WebGPU), using about ${(AI_MODEL.vramMB / 1000).toFixed(1)} GB of its memory.`),
      h('li', {}, h('b', {}, 'After that: '), 'it works without internet. The model stays in this browser\'s storage until the site data is cleared.'),
      h('li', {}, h('b', {}, 'Your words: '), `nothing you write leaves this computer and nothing is saved. The AI gets only what you type here${kind === 'analyse' ? ' and the lines this panel shows' : ''}; private logs never go to it.`)),
    h('div', { class: 'actions' },
      btn('primary small', local ? 'Load and start' : 'Download and start', onYes, 'check', { 'data-fk': 'ai:yes' }),
      btn('secondary small', 'Not now', onNo, 'x')));
}

function progressView() {
  const bar = h('progress', { max: '100', value: '0', 'aria-label': 'AI model loading' });
  const text = h('p', { class: 'ai-progress-text', 'aria-live': 'polite' }, 'Starting the AI on this computer.');
  let said = -10;
  let lastPhase = '';
  const words = { download: 'Downloading the model', cache: 'Loading the model from this browser\'s storage', gpu: 'Preparing the graphics chip', start: 'Starting the AI' };
  const update = ({ part, phase }) => {
    const pct = Math.max(0, Math.min(100, Math.round(part * 100)));
    bar.value = pct;
    // The words change at most every 10 percent, so a screen reader is not flooded.
    if (phase !== lastPhase || pct - said >= 10 || pct === 100) {
      said = pct;
      lastPhase = phase;
      text.textContent = `${words[phase] || words.start}: ${pct}%.${phase === 'download' ? ` About ${Math.round((AI_MODEL.downloadMB * pct) / 100)} of ${AI_MODEL.downloadMB} MB.` : ''}`;
    }
  };
  return { node: h('div', { class: 'ai-progress', tabindex: '-1' }, bar, text), update };
}

const SESSION_LABEL = 'AI support: a program, not a person';
// The model sometimes writes Markdown and long dashes; the panel shows plain text (as text, never as HTML), with a
// range dash read as "to" and any other long dash as a comma, like the program's own text.
export const plainMd = (t) => String(t).replace(/\*\*([^*]+)\*\*/g, '$1').replace(/__([^_]+)__/g, '$1').replace(/^#{1,6}\s+/gm, '').replace(/^(\s*)[*-] /gm, '$1\u2022 ')
  .replace(/(\d)\s*[\u2013\u2014]\s*(\d)/g, '$1 to $2').replace(/\s*[\u2013\u2014]\s*/g, ', ');
const msgNode = (role, text, { held = null, label = LABEL } = {}) => h('div', { class: `ai-msg ${role === 'user' ? 'me' : 'ai'}${held ? ' held' : ''}` },
  h('p', { class: 'ai-who' }, role === 'user' ? 'You' : held ? `Held back by the rule "${(ruleById(held) || {}).title || held}"` : label),
  h('p', { class: 'ai-text' }, text));

// host: the element to draw in. kind: 'analyse' or 'session'. ctx: { level, red, data } for 'analyse'.
// space(): where the crew is now, asked at every question: { mission, linkDown, doctorOnBoard } (src/ai-rules.js).
// onRisk(): opens Help now (the session's own card). helpNow(): returns a Help now card (the analyse panel).
export function renderAi(host, { kind, ctx = {}, space = null, onRisk = null, helpNow = null } = {}) {
  // The link or the profile can change while the panel is open, so each question gets them as they are now.
  const ctxNow = () => ({ ...ctx, ...(typeof space === 'function' ? space() : {}) });
  const place = kind === 'session' ? 'session' : 'analyse';
  const body = h('div', { class: 'ai-body' });
  const root = h('div', { class: `ai-part ${reduceMotion() ? 'still' : ''}` }, body, rulesList(kind));
  fill(host, root);
  talk = { kind, history: [], shown: false };
  const mine = talk;

  const plain = (title, text, extra = null) => fill(body, h('div', { class: 'ai-card', role: 'status' }, h('p', { class: 'tp-title' }, title), h('p', {}, text), extra));
  const rulesOnly = place === 'session'
    ? 'Everything else here works as before: Help now, the coping steps, writing it out and Tell the doctor on Earth.'
    : 'Everything else works as before: the levels, What to do and Message the doctor come from the automation.';

  // byClick: the person pressed a button that is now gone, so the keyboard focus follows to what replaced it.
  const start = async (byClick = false) => {
    agreed = true;
    const p = progressView();
    fill(body, p.node);
    if (byClick) p.node.focus();
    try {
      await startAi({ onProgress: p.update });
    } catch (e) {
      plain('The AI could not start', `${e.message} ${rulesOnly}`, h('div', { class: 'actions' }, btn('secondary small', 'Try again', () => start(true), 'sparkles')));
      return;
    }
    if (talk !== mine) return;
    ready(byClick || (globalThis.document && body.contains(document.activeElement)));
  };

  const ready = (focus = false) => (kind === 'session' ? chat(focus) : explain(focus));
  // The model was let go while answering: say so once, keep the rest of the panel, offer to start again.
  const stopped = (e) => { if (talk === mine) plain('The AI stopped', `${e.message} ${rulesOnly}`, h('div', { class: 'actions' }, btn('secondary small', 'Start the AI again', () => start(true), 'sparkles'))); };

  // ---------- the session: a real chat, nothing saved or sent ----------
  const chat = (focus = false) => {
    const log = h('div', { class: 'ai-log', role: 'log', 'aria-live': 'polite', 'aria-label': 'Talk with the AI' });
    const box = h('textarea', { class: 'ai-input', rows: '3', 'aria-label': 'Write to the AI. Not saved.', placeholder: 'Write to the AI. Not saved, not sent.', 'data-session': '', 'data-nodraft': '' });
    const send = btn('primary small', 'Send', () => go(), 'send', { 'data-fk': 'ai:send' });
    const stop = btn('secondary small', 'Stop', () => interrupt(), 'square', { hidden: true });
    box.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); go(); } });
    let busy = false;
    const go = async () => {
      const text = box.value.trim();
      if (!text || busy) return;
      box.value = '';
      log.append(msgNode('user', text));
      mine.history.push({ role: 'user', content: text });
      mine.shown = true;
      const out = msgNode('assistant', 'Writing.', { label: SESSION_LABEL });
      out.querySelector('.ai-text').classList.add('pending');
      log.append(out);
      out.scrollIntoView({ block: 'nearest' });
      busy = true;
      send.disabled = true;
      stop.hidden = false;
      try {
        const res = await askAi({ kind: 'session', history: mine.history, ctx: ctxNow(), onText: (t) => { const n = out.querySelector('.ai-text'); n.textContent = plainMd(t); n.classList.remove('pending'); } });
        if (talk !== mine) return;
        if (res.risk) {
          // Layer 1: the model never answers these words; Help now opens first.
          mine.history.pop();
          out.replaceWith(msgNode('assistant', 'Help now is open. This AI does not answer this message: please reach a person now, a crewmate or the ground. Nothing was sent.', { held: 'risk-words-first' }));
          if (onRisk) onRisk();
        } else {
          // A held exchange stays on screen but leaves the model's memory, so the model never sees (or copies) it.
          if (res.held) { out.replaceWith(msgNode('assistant', res.text, { held: res.held })); mine.history.pop(); } else mine.history.push({ role: 'assistant', content: res.text });
        }
      } catch (e) {
        out.replaceWith(msgNode('assistant', `No answer: ${e.message}`, { label: SESSION_LABEL }));
        mine.history.pop();
        if (aiState().phase === 'failed') stopped(e);
      } finally {
        busy = false;
        send.disabled = false;
        stop.hidden = true;
        if (talk === mine) box.focus();
      }
    };
    fill(body,
      h('p', { class: 'ai-label' }, supIcon('sparkles', { size: 16 }), 'AI support on this computer: a program, not a person and not a psychologist. Nothing you write is saved or sent.'),
      log,
      h('label', { class: 'log-field' }, h('span', {}, 'Write to the AI (not saved)'), box),
      h('div', { class: 'actions' }, send, stop, btn('secondary small', 'Forget the talk', async () => { log.replaceChildren(); mine.history = []; await forgetTalk(); box.focus(); }, 'x')));
    if (focus) box.focus();
  };

  // ---------- Analyse with AI: an explanation of the readings the panel shows ----------
  const explain = (focus = false) => {
    const answer = h('div', { class: 'ai-log', role: 'log', 'aria-live': 'polite', 'aria-label': 'The AI\'s explanation', tabindex: '-1' });
    const q = h('input', { type: 'text', class: 'ai-q', 'aria-label': 'Ask about these readings. Not saved.', placeholder: 'Ask about these readings (not saved)', 'data-nodraft': '' });
    const ask = btn('secondary small', 'Ask', () => go(q.value.trim()), 'send');
    q.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.isComposing) { e.preventDefault(); go(q.value.trim()); } });
    let busy = false;
    const go = async (text) => {
      if (!text || busy) return;
      busy = true;
      ask.disabled = true;
      q.value = '';
      // The first question is the panel's own ("Explain these readings"), so it is not shown as the person's.
      const first = !mine.started;
      mine.started = true;
      if (!first) answer.append(msgNode('user', text));
      mine.history.push({ role: 'user', content: text });
      const out = msgNode('assistant', 'Writing.');
      out.querySelector('.ai-text').classList.add('pending');
      answer.append(out);
      try {
        const res = await askAi({ kind: 'analyse', history: mine.history, ctx: ctxNow(), onText: (t) => { const n = out.querySelector('.ai-text'); n.textContent = plainMd(t); n.classList.remove('pending'); } });
        if (talk !== mine) return;
        if (res.risk) {
          mine.history.pop();
          out.replaceWith(msgNode('assistant', 'Help now is shown below. This AI does not answer this message: please reach a person now. Nothing was sent.', { held: 'risk-words-first' }));
          if (helpNow) answer.append(helpNow());
        } else {
          // A held exchange stays on screen but leaves the model's memory, so the model never sees (or copies) it.
          if (res.held) { out.replaceWith(msgNode('assistant', res.text, { held: res.held })); mine.history.pop(); } else mine.history.push({ role: 'assistant', content: res.text });
        }
      } catch (e) {
        out.replaceWith(msgNode('assistant', `No answer: ${e.message}`));
        mine.history.pop();
        if (aiState().phase === 'failed') stopped(e);
      } finally {
        busy = false;
        ask.disabled = false;
      }
    };
    fill(body,
      ctx.red ? h('p', { class: 'ai-red', role: 'note' }, supIcon('circle-alert', { size: 18 }), 'A reading is past a red limit: follow the numbered steps in What to do and use Message the doctor. This line is fixed, not AI.') : null,
      answer,
      h('div', { class: 'ai-ask' }, q, ask));
    if (focus) answer.focus();
    go('Explain these readings to me in plain words.');
  };

  // ---------- what can run here ----------
  (async () => {
    const can = await aiSupport();
    if (talk !== mine) return;
    if (!can.ok) { plain('The AI cannot run in this browser', `${can.why} ${rulesOnly}`); return; }
    if (aiState().phase === 'ready') { ready(); return; }
    const source = await modelSource();
    if (talk !== mine) return;
    if (agreed || aiState().phase === 'loading' || (await isStored(source))) { start(); return; }
    fill(body, consentCard(source, kind, {
      onYes: () => start(true),
      onNo: () => plain('The AI is not started', `Nothing was downloaded. ${rulesOnly}`, h('div', { class: 'actions' }, btn('secondary small', 'Start the AI', () => ready0(), 'sparkles'))),
    }));
    const ready0 = () => fill(body, consentCard(source, kind, { onYes: () => start(true), onNo: () => plain('The AI is not started', `Nothing was downloaded. ${rulesOnly}`) }));
  })();
  return root;
}

// The panel closed: forget the talk. Returns true when there was one to forget.
export function endTalk() {
  const had = Boolean(talk && talk.shown);
  talk = null;
  interrupt();
  forgetTalk();
  return had;
}
